// Merges what the model extracted back onto the job spec.
//
// The model's output is treated as untrusted input, because it is. Every value is
// validated, capped and normalised before it can influence who gets a text message:
//
//   - the reply may arrive wrapped in a code fence, or with a sentence in front of it
//   - it may be valid JSON of entirely the wrong shape
//   - it may return forty skills when it was asked for twelve
//   - the API may have returned an error object with a 200, because the HTTP node is set
//     to neverError so that a failure here cannot take the campaign down
//
// Any of those falls back to the ATS skill list and the run continues. An AI step that can
// fail a job order is worse than no AI step.
const cfg = $('config').first().json;
const job = $('read the job order').first().json;
const res = $input.first().json || {};

const clean = (s) => String(s || '').toLowerCase().trim()
  .replace(/^[-*\d.)\s]+/, '')     // list bullets the model added anyway
  .replace(/\s+/g, ' ')
  .slice(0, 60);

// Anthropic returns { content: [ { type: 'text', text: '...' } ] }. An error returns
// { type: 'error', error: { message } } — with a 200, because of neverError.
let raw = '';
if (Array.isArray(res.content)) {
  raw = res.content.filter((b) => b && b.type === 'text').map((b) => b.text).join('\n');
} else if (typeof res.completion === 'string') {
  raw = res.completion;
}

const apiError = res.error ? String(res.error.message || res.error.type || 'API error')
  : (res.type === 'error' ? 'API returned an error' : '');

// Pull the first {...} out of whatever came back. Handles a bare object, a fenced block,
// and a model that felt like explaining itself first.
function extractJson(text) {
  const s = String(text || '');
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced ? fenced[1] : s;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    return JSON.parse(candidate.slice(start, end + 1));
  } catch (e) {
    return null;
  }
}

const parsed = extractJson(raw);
const cap = Number(cfg.ai_max_skills) || 12;

const asSkills = (v) => (Array.isArray(v) ? v : [])
  .map(clean)
  .filter((x) => x.length > 1 && x.length < 60)
  .filter((x, i, a) => a.indexOf(x) === i)
  .slice(0, cap);

const aiRequired = parsed ? asSkills(parsed.required_skills) : [];
const aiNice = parsed ? asSkills(parsed.nice_to_have) : [];

// The ATS list always wins where the two disagree — a recruiter typed it, and the model
// only ever adds to it.
const merged = job.required_skills.slice();
for (const s of aiRequired) if (merged.indexOf(s) === -1) merged.push(s);
const mergedNice = job.nice_to_have.slice();
for (const s of aiNice) if (mergedNice.indexOf(s) === -1 && merged.indexOf(s) === -1) {
  mergedNice.push(s);
}

const used = merged.length > job.required_skills.length || mergedNice.length > job.nice_to_have.length;

let note;
if (apiError) note = 'the AI call failed (' + apiError + ') — keyword rules only';
else if (!parsed) note = 'the AI reply could not be parsed as JSON — keyword rules only';
else if (!used) note = 'the AI added nothing the ATS did not already have';
else note = 'the AI added ' + (merged.length - job.required_skills.length) + ' required and '
  + (mergedNice.length - job.nice_to_have.length) + ' preferred skills';

return [{
  json: Object.assign({}, job, {
    required_skills: merged,
    nice_to_have: mergedNice,
    // A shift or a certification the model spotted in the prose is useful on the ATS note
    // and in the SMS, but it is never allowed to gate anybody.
    _ai_shift: parsed && typeof parsed.shift === 'string' ? clean(parsed.shift) : '',
    _ai_certifications: parsed ? asSkills(parsed.certifications) : [],
    _ai_used: used,
    _ai_note: note,
    _ai_model: cfg.ai_model,
    _ai_raw_reply: String(raw).slice(0, 1200),
    _skills_before_ai: job.required_skills.length,
    _skills_after_ai: merged.length,
    _tokens: res.usage
      ? { in: res.usage.input_tokens, out: res.usage.output_tokens } : null
  })
}];

// The AI reader was not called. Either the ATS already gave a real skill list, or no key
// is configured. Either way the job spec passes through untouched.
//
// This branch exists so the merge downstream always has an item, and so the reason is
// visible in the execution list rather than inferred from a node that did not light up.
const cfg = $('config').first().json;
const job = $input.first().json;

const why = !cfg.ai_enabled
  ? 'no AI_API_KEY in config — keyword rules only'
  : (!job._needs_ai
    ? 'the ATS supplied ' + job._skills_from_ats + ' skills, which is enough to match on'
    : 'the job description was too short to be worth reading');

return [{
  json: Object.assign({}, job, {
    _ai_used: false,
    _ai_note: why,
    _skills_before_ai: (job.required_skills || []).length,
    _skills_after_ai: (job.required_skills || []).length,
    _ai_shift: '',
    _ai_certifications: []
  })
}];

// No ATS connected. Rather than ending the run, the engine hands the pipeline a small pool
// of fabricated candidates so every node downstream can be watched working. This is the
// state the walkthrough video is recorded in.
//
// Each row exists to exercise one branch of the gate. Do not tidy them up. Every number is
// in the 555-01XX reserved range and every address is at example.com.
return [
  { json: { id: 'C-1001', firstName: 'Marcus', lastName: 'Ellison', email: 'user@example.com',
      mobile: '(614) 555-0142', occupation: 'Forklift Operator',
      skillSet: 'forklift, pallet jack, shipping, RF scanner',
      address: { city: 'Columbus', state: 'OH' }, status: 'Active' } },

  { json: { id: 'C-1002', firstName: 'Danielle', lastName: 'Okafor', email: 'user@example.com',
      mobile: '614.555.0177', occupation: 'Warehouse Associate',
      skillSet: 'forklift certified; shipping; receiving; inventory',
      address: { city: 'Columbus', state: 'OH' }, status: 'Available' } },

  // The same human as C-1002 under a second ATS record, with the number written a third
  // way. Must collapse to one person, not be texted twice.
  { json: { id: 'C-1003', firstName: 'Danielle', lastName: 'Okafor', email: 'user@example.com',
      mobile: '+1234567890', occupation: 'Warehouse', skillSet: '',
      address: { city: 'Columbus', state: 'OH' }, status: 'Active' } },

  // Opted out three weeks ago. Scores well. Must never be contacted.
  { json: { id: 'C-1004', firstName: 'Priya', lastName: 'Raman', email: 'user@example.com',
      mobile: '(614) 555-0188', occupation: 'Forklift Driver',
      skillSet: 'forklift, RF scanner, cycle counting',
      address: { city: 'Columbus', state: 'OH' }, status: 'Active' } },

  // Placed last month. Texting a placed candidate about a new role is how an agency loses
  // the client whose worker it just poached.
  { json: { id: 'C-1005', firstName: 'Tomas', lastName: 'Ibarra', email: 'user@example.com',
      mobile: '(614) 555-0155', occupation: 'Forklift Operator', skillSet: 'forklift, shipping',
      address: { city: 'Columbus', state: 'OH' }, status: 'Placed' } },

  // A placeholder typed into the mobile field, with a real landline underneath. Twilio
  // would answer 30003 on the first and charge for it.
  { json: { id: 'C-1006', firstName: 'Yvette', lastName: 'Braun', email: 'user@example.com',
      mobile: '+1234567890', phone: '614-555-0121', occupation: 'Shipping Clerk',
      skillSet: 'shipping, receiving', address: { city: 'Dublin', state: 'OH' }, status: 'Active' } },

  // Contacted six hours ago about a different job order. Inside the cooldown.
  { json: { id: 'C-1007', firstName: 'Andre', lastName: 'Whitlock', email: 'user@example.com',
      mobile: '(614) 555-0199', occupation: 'Material Handler', skillSet: 'forklift, pallet jack',
      address: { city: 'Columbus', state: 'OH' }, status: 'Active' } },

  // Right skills, wrong state. Still scores; the distance shows up in the reasons.
  { json: { id: 'C-1008', firstName: 'Renata', lastName: 'Voss', email: 'user@example.com',
      mobile: '(313) 555-0164', occupation: 'Forklift Operator', skillSet: 'forklift, shipping, OSHA',
      address: { city: 'Detroit', state: 'MI' }, status: 'Active' } },

  // Nothing in common with the job order. Below the floor, stored with the reason.
  { json: { id: 'C-1009', firstName: 'Owen', lastName: 'Castellanos', email: 'user@example.com',
      mobile: '(614) 555-0133', occupation: 'Graphic Designer', skillSet: 'illustrator, figma',
      address: { city: 'Columbus', state: 'OH' }, status: 'Active' } },

  // No phone at all. Cannot be texted or called; kept in the database, not enrolled.
  { json: { id: 'C-1010', firstName: 'Sasha', lastName: 'Nurse', email: 'user@example.com',
      mobile: '', occupation: 'Forklift Operator', skillSet: 'forklift, inventory',
      address: { city: 'Columbus', state: 'OH' }, status: 'Active' } },

  // A row the ATS export left half-empty. No id, so it cannot be tracked at all.
  { json: { id: '', firstName: '', lastName: '', mobile: '(614) 555-0102', skillSet: '' } }
];

// Every candidate from every ATS becomes the same object here. Two things matter:
//
//   1. The phone becomes E.164 or it becomes null. "(614) 555-0142", "614.555.0142" and
//      "+1234567890" are one number, and if they are not normalised on the way in then
//      the opt-out table cannot match them and somebody who texted STOP gets texted again.
//   2. A dedupe key is computed here rather than left to the database, so the run can
//      report "the same person is in your ATS four times" instead of silently collapsing it.
const cfg = $('config').first().json;
const map = (cfg.ats_fields && cfg.ats_fields.candidate) || {};
const exclude = (cfg.ats_exclude_statuses || []).map((s) => String(s).toLowerCase());

const dig = (obj, path) => {
  if (!path) return undefined;
  return String(path).split('.').reduce(
    (o, k) => (o === null || o === undefined ? undefined : o[k]), obj);
};
const str = (v) => (v === null || v === undefined ? '' : String(v).trim());

const asList = (v) => {
  if (!v) return [];
  const flat = Array.isArray(v) ? v : String(v).split(/[,;|]/);
  return flat
    .map((x) => (x && typeof x === 'object' ? (x.name || x.label || x.value || '') : x))
    .map((x) => str(x).toLowerCase())
    .filter((x) => x.length > 1);
};

// North American numbers. Anything else is left alone and flagged, because guessing a
// country code is how you call a stranger in another timezone at 3am.
function toE164(value) {
  const raw = str(value);
  if (!raw) return { phone: null, why: 'no number on the record' };
  if (/^\+[1-9]\d{7,14}$/.test(raw.replace(/[\s()-]/g, ''))) {
    return { phone: raw.replace(/[\s()-]/g, ''), why: '' };
  }
  const digits = raw.replace(/\D/g, '');
  if (digits.length === 11 && digits[0] === '1') return { phone: '+' + digits, why: '' };
  if (digits.length === 10) {
    // NANP: area code and exchange both start 2-9. Catches +1234567890 placeholders.
    if (digits[0] < '2' || digits[3] < '2') {
      return { phone: null, why: 'not a valid North American number: ' + raw };
    }
    return { phone: '+1' + digits, why: '' };
  }
  if (digits.length > 11) return { phone: null, why: 'looks international, left for review: ' + raw };
  return { phone: null, why: 'unusable number: ' + raw };
}

const items = $input.all().map((i) => i.json).filter((r) => r && !r._empty_placeholder);

// Some ATS search endpoints return {data:[...]}, some return the array, some paginate into
// {results:[...]}. Flatten whichever arrived.
let rows = [];
for (const it of items) {
  if (Array.isArray(it.data)) rows = rows.concat(it.data);
  else if (Array.isArray(it.results)) rows = rows.concat(it.results);
  else if (Array.isArray(it.candidates)) rows = rows.concat(it.candidates);
  else rows.push(it);
}

const seen = new Map();
const out = [];
const skipped = { no_id: 0, no_phone: 0, excluded_status: 0, duplicate_in_ats: 0 };

for (const r of rows) {
  const ats_candidate_id = str(dig(r, map.id) || r.id || r.candidate_id);
  if (!ats_candidate_id) { skipped.no_id++; continue; }

  const first_name = str(dig(r, map.first_name) || r.first_name);
  const last_name = str(dig(r, map.last_name) || r.last_name);
  const status = str(dig(r, map.status) || r.status);

  if (status && exclude.indexOf(status.toLowerCase()) !== -1) {
    skipped.excluded_status++;
    continue;   // Placed / Do Not Contact. Dropped here, never scored, never stored as eligible.
  }

  // Mobile first: an SMS to a landline is a guaranteed Twilio 30003 and a wasted segment.
  const primary = toE164(dig(r, map.phone) || r.mobile);
  const fallback = primary.phone ? primary : toE164(dig(r, map.phone_alt) || r.phone);
  const phone_e164 = primary.phone || fallback.phone;
  const phone_note = phone_e164 ? '' : (primary.why || fallback.why);

  const candidate = {
    ats_candidate_id: ats_candidate_id,
    first_name: first_name,
    last_name: last_name,
    full_name: (first_name + ' ' + last_name).trim() || ('candidate ' + ats_candidate_id),
    email: str(dig(r, map.email) || r.email).toLowerCase(),
    phone_e164: phone_e164,
    _phone_note: phone_note,
    title: str(dig(r, map.title) || r.title),
    skills: asList(dig(r, map.skills) || r.skills),
    city: str(dig(r, map.city)),
    state: str(dig(r, map.state)).toUpperCase().slice(0, 2),
    timezone: str(r.timezone) || cfg.default_timezone,
    ats_status: status,
    _source_row: ats_candidate_id
  };

  if (!phone_e164) skipped.no_phone++;

  // Duplicate defence #3, and the only one that runs before anything is written: the same
  // human under two ATS ids. Keep the record with the most on it rather than the first seen.
  const key = phone_e164 || ('email:' + candidate.email) || ('name:' + candidate.full_name.toLowerCase());
  if (phone_e164 || candidate.email) {
    const prior = seen.get(key);
    if (prior) {
      skipped.duplicate_in_ats++;
      prior._duplicate_ats_ids = (prior._duplicate_ats_ids || []).concat(ats_candidate_id);
      const weight = (c) => (c.skills.length ? 2 : 0) + (c.email ? 1 : 0) + (c.title ? 1 : 0);
      if (weight(candidate) > weight(prior)) {
        candidate._duplicate_ats_ids = prior._duplicate_ats_ids;
        out[out.indexOf(prior)] = candidate;
        seen.set(key, candidate);
      }
      continue;
    }
    seen.set(key, candidate);
  }
  out.push(candidate);
}

if (!out.length) {
  return [{ json: { _no_candidates: true, _skipped: skipped, _rows_from_ats: rows.length } }];
}

return out.map((c) => ({
  json: Object.assign(c, {
    _no_candidates: false,
    _skipped: skipped,
    _rows_from_ats: rows.length,
    _unique_people: out.length
  })
}));

// A transparent score. Every point is attributable to a rule with a name, so the sentence
// "why did we text this person about a forklift job" always has an answer that fits on one
// line — which is the thing an embedding similarity cannot give a staffing manager.
const cfg = $('config').first().json;
const w = cfg.match || {};
const job = $('the job spec').first().json;

const candidates = $input.all().map((i) => i.json).filter((c) => c && !c._no_candidates);

// "Forklift Operator" vs "Warehouse Forklift Driver" share `forklift`. Stop words removed
// so "of", "and" and "the" do not manufacture a match.
const STOP = new Set(['a','an','and','the','of','for','to','in','at','with','or','ii','iii',
  'senior','junior','lead','level','i','ft','pt','temp','contract']);
const words = (s) => String(s || '').toLowerCase().split(/[^a-z0-9+#]+/)
  .filter((x) => x.length > 2 && !STOP.has(x));

const jobTitleWords = new Set(words(job.title));
const required = job.required_skills || [];
const nice = job.nice_to_have || [];

// A skill matches if either string contains the other: "forklift" matches "forklift certified",
// and "excel" does not match "excellent".
const hasSkill = (skills, want) => skills.some((s) => {
  const a = s.toLowerCase(), b = String(want).toLowerCase();
  return a === b || (a.length > 3 && b.length > 3 && (a.includes(b) || b.includes(a)));
});

// The description is the fallback when the ATS skill list is empty, which for most job
// orders it is. Pulling the required skills out of prose is a genuine weak point and it is
// called out in the README rather than hidden.
const descWords = new Set(words(job.description));

const scored = candidates.map((c) => {
  let score = 0;
  const reasons = [];
  const skills = c.skills || [];

  let hits = 0;
  for (const s of required) {
    if (hasSkill(skills, s)) { hits++; score += w.required_skill || 0; }
  }
  if (hits) reasons.push(hits + ' of ' + required.length + ' required skills');

  let niceHits = 0;
  for (const s of nice) {
    if (hasSkill(skills, s)) { niceHits++; score += w.nice_skill || 0; }
  }
  if (niceHits) reasons.push(niceHits + ' preferred skills');

  // No skill list on either side: fall back to their title against the description.
  if (!required.length && descWords.size) {
    const overlap = words(c.title).filter((x) => descWords.has(x));
    if (overlap.length) {
      score += Math.min(overlap.length, 3) * (w.required_skill || 0) / 2;
      reasons.push('title words in the job description: ' + overlap.slice(0, 3).join(', '));
    }
  }

  const titleOverlap = words(c.title).filter((x) => jobTitleWords.has(x));
  if (titleOverlap.length) {
    score += w.title_overlap || 0;
    reasons.push('title matches on ' + titleOverlap.slice(0, 2).join(', '));
  }

  if (job.city && c.city && job.city.toLowerCase() === c.city.toLowerCase()) {
    score += w.same_city || 0;
    reasons.push('same city');
  } else if (job.state && c.state && job.state === c.state) {
    score += w.same_state || 0;
    reasons.push('same state');
  } else if (job.state && c.state && job.state !== c.state) {
    reasons.push('out of state (' + c.state + ')');
  }

  const active = ['active', 'available', 'placed - available', 'new lead', 'submitted',
    'contacted', 'qualifying'];
  if (c.ats_status && active.indexOf(c.ats_status.toLowerCase()) !== -1) {
    score += w.recent_activity || 0;
    reasons.push('ATS status "' + c.ats_status + '"');
  }

  if (c.phone_e164) {
    score += w.has_mobile || 0;
  } else {
    reasons.push('no usable mobile — cannot be texted or called');
  }

  score = Math.max(0, Math.round(score));

  return Object.assign({}, c, {
    match_score: score,
    match_reasons: reasons,
    _above_floor: score >= (cfg.min_match_score || 0),
    _job_title: job.title,
    _ats_job_id: job.ats_job_id
  });
});

scored.sort((a, b) => b.match_score - a.match_score);

// Everyone is returned, including those below the floor. They are stored with their score
// and their reason, so "why was this person not contacted" is answerable too — and so the
// floor can be lowered next week without re-pulling 20,000 records.
return scored.map((c, i) => ({ json: Object.assign(c, { _rank: i + 1, _pool_size: scored.length }) }));

// Shapes what Supabase returned into the one object the gate expects, so the gate does not
// care whether the history came from the database or from the demo stub.
//
// One request, not three: the HTTP node calls an RPC that returns
// { opt_outs, recent_touches, active_phones, enrolled_ats_ids } in a single round trip.
// Three separate REST calls would be three chances for a partial failure to produce a
// half-populated suppression list, which is worse than none.
const job = $('the job spec').first().json;
const raw = $input.first().json || {};
const body = Array.isArray(raw) ? (raw[0] || {}) : (raw.data || raw);

const arr = (v) => (Array.isArray(v) ? v : []);

// recent_touches arrives as [{phone_e164, last_attempt_at}]; the gate wants a lookup.
const last_touch = {};
for (const t of arr(body.recent_touches)) {
  const p = t && (t.phone_e164 || t.phone);
  if (p && t.last_attempt_at) last_touch[String(p)] = t.last_attempt_at;
}

const optOuts = arr(body.opt_outs).map((o) =>
  (typeof o === 'string' ? { phone_e164: o } : o)).filter((o) => o && o.phone_e164);

// A Supabase call that succeeded but returned nothing is a real answer (a brand new client
// genuinely has no opt-outs). A call that errored is not, and must not read as one.
const errored = !!(raw.error || raw.message || raw.code) && !body.opt_outs;

return [{
  json: {
    _source: errored ? 'supabase — ERRORED' : 'supabase',
    opt_outs: optOuts,
    last_touch: last_touch,
    active_phones: arr(body.active_phones).map(String),
    enrolled_ats_ids: arr(body.enrolled_ats_ids).map(String),
    _counts: {
      opt_outs: optOuts.length,
      recent_touches: Object.keys(last_touch).length,
      active_elsewhere: arr(body.active_phones).length,
      already_enrolled: arr(body.enrolled_ats_ids).length
    },
    _job: job.ats_job_id,
    _warning: errored
      ? 'The engagement history query failed (' + (raw.message || raw.error || raw.code)
        + '). The gate is running with an EMPTY suppression list — treat this run as '
        + 'preview and investigate before going live.'
      : ''
  }
}];

// Supabase is not connected, so there is no opt-out list and no contact history to check
// against. In demo mode the engine substitutes a small fabricated history — which is what
// makes the opted-out candidate and the cooldown candidate visible in the walkthrough.
//
// With DEMO_MODE off and Supabase unconfigured this returns an EMPTY history and says so
// loudly. An empty opt-out list is not the same as nobody having opted out, and that
// warning is carried through to the end of the run rather than dropped here.
const cfg = $('config').first().json;

if (cfg.demo_mode) {
  return [{
    json: {
      _source: 'demo — fabricated history, not real opt-outs',
      opt_outs: [{ phone_e164: '+1234567890' }],          // Priya, three weeks ago
      last_touch: { '+1234567890': new Date(Date.now() - 6 * 3600 * 1000).toISOString() },
      active_phones: [],
      enrolled_ats_ids: [],
      _warning: ''
    }
  }];
}

return [{
  json: {
    _source: 'none — Supabase not configured',
    opt_outs: [],
    last_touch: {},
    active_phones: [],
    enrolled_ats_ids: [],
    _warning: 'No opt-out list was available for this run, so no suppression could be '
      + 'applied. Nothing was sent — the first touch is scheduled by workflow 2, which '
      + 'checks the opt-out table again before it sends anything.'
  }
}];

// THE GATE. Nothing is enrolled that does not pass every check here, and every rejection
// is recorded with the reason next to the name rather than dropped.
//
// This node's $input is the engagement history (opt-outs and recent attempts, one item);
// the candidates come from the scored node. That way a Supabase outage produces an empty
// history and a run that stops, not a run that contacts everybody.
const cfg = $('config').first().json;
const job = $('the job spec').first().json;
const scored = $('score against the job order').all().map((i) => i.json)
  .filter((c) => c && c.ats_candidate_id);

const hist = $input.first().json || {};
const optOuts = new Set((hist.opt_outs || []).map((o) =>
  String(typeof o === 'string' ? o : o.phone_e164 || '')).filter(Boolean));
// phone -> ISO timestamp of the last outbound touch, from any campaign
const lastTouch = hist.last_touch || {};
// phones already live in another campaign
const activeElsewhere = new Set((hist.active_phones || []).map(String));
// ats ids already enrolled in THIS campaign (a re-delivered webhook, or a second run)
const alreadyEnrolled = new Set((hist.enrolled_ats_ids || []).map(String));

const now = Date.now();
const minGapMs = (Number(cfg.min_hours_between_touches) || 0) * 3600 * 1000;

const held = [];
const eligible = [];

for (const c of scored) {
  const hold = (reason) => { held.push(Object.assign({}, c, { hold_reason: reason })); };

  // Order matters. The cheapest and most legally consequential checks come first, and
  // opt-out comes before everything including the score — an opted-out number is never
  // reconsidered because the job is a good fit.
  if (!c.phone_e164) { hold('no usable mobile number' + (c._phone_note ? ' — ' + c._phone_note : '')); continue; }
  if (optOuts.has(c.phone_e164)) { hold('opted out — never contact'); continue; }
  if (alreadyEnrolled.has(String(c.ats_candidate_id))) { hold('already enrolled in this campaign'); continue; }
  if (activeElsewhere.has(c.phone_e164)) { hold('already being worked by another live campaign'); continue; }

  const last = lastTouch[c.phone_e164];
  if (last && minGapMs > 0) {
    const age = now - new Date(last).getTime();
    if (Number.isFinite(age) && age < minGapMs) {
      hold('contacted ' + Math.round(age / 3600000) + 'h ago, inside the '
        + cfg.min_hours_between_touches + 'h cooldown');
      continue;
    }
  }

  if (!c._above_floor) {
    hold('match score ' + c.match_score + ' below the floor of ' + cfg.min_match_score);
    continue;
  }

  eligible.push(c);
}

// Already sorted by score. Take the top N and hold the rest with a reason that says they
// are not rejected, only queued — a second push for the same job picks them up.
const topN = Number(cfg.enroll_top_n) || 25;
const enrolled = eligible.slice(0, topN);
for (const c of eligible.slice(topN)) {
  held.push(Object.assign({}, c, {
    hold_reason: 'eligible, outside the top ' + topN + ' this run — rank ' + c._rank
  }));
}

const firstStep = (cfg.sequence || [])[0] || { step: 1, channel: 'sms', delay_hours: 0 };

const summary = {
  _stage: 'gate',
  job_title: job.title,
  ats_job_id: job.ats_job_id,
  pool: scored.length,
  eligible: eligible.length,
  enrolled: enrolled.length,
  held: held.length,
  held_by_reason: held.reduce((acc, h) => {
    const k = String(h.hold_reason).replace(/\d+/g, 'N').split(' — ')[0];
    acc[k] = (acc[k] || 0) + 1; return acc;
  }, {}),
  history_source: hist._source || 'unknown'
};

if (!enrolled.length) {
  return [{ json: Object.assign({ _has_enrollments: false, held: held }, summary) }];
}

return enrolled.map((c) => ({
  json: Object.assign({}, c, {
    _has_enrollments: true,
    _summary: summary,
    _held: held,
    // The first touch is scheduled, not sent. Workflow 2 owns every send, which is what
    // keeps quiet hours and the daily cap in one place instead of two.
    step: 0,
    attempts_made: 0,
    status: 'pending',
    next_attempt_at: new Date(now + (Number(firstStep.delay_hours) || 0) * 3600000).toISOString(),
    campaign_idempotency_key: job.idempotency_key,
    // Per-enrollment key, so re-running this workflow for the same job on the same day
    // updates rather than duplicates.
    enrollment_key: ['enr', cfg.client_slug, job.ats_job_id, c.ats_candidate_id].join(':')
  })
}));

// The pool was pulled and scored, and nobody came out the other side. That is a legitimate
// outcome for a narrow job order, so it is reported with the arithmetic — which is what
// tells it apart from a broken run.
const j = $input.first().json;
const held = j.held || [];

return [{
  json: {
    _outcome: 'nobody eligible',
    job_title: j.job_title,
    ats_job_id: j.ats_job_id,
    candidates_scored: j.pool || 0,
    held_back: held.length,
    held_by_reason: j.held_by_reason || {},
    examples: held.slice(0, 10).map((h) => ({
      name: h.full_name, score: h.match_score, reason: h.hold_reason
    })),
    _next_step: 'If most rows say "below the floor", MIN_MATCH_SCORE is too high for this '
      + 'job order, or the ATS skill list was empty and there was nothing to match on. If '
      + 'most say "no usable mobile", the candidate field map is pointing at the wrong '
      + 'phone field for this vendor.'
  }
}];

// Builds the three upsert payloads the launch writes, in the order the foreign keys need:
// job order, then candidates, then enrollments.
//
// Every payload is an ARRAY sent in ONE request. Twenty-five candidates is one round trip
// with `Prefer: resolution=merge-duplicates`, not twenty-five — which matters less for 25
// than it does for the nightly 20,000-row candidate sync that uses this same shape.
const cfg = $('config').first().json;
const job = $('the job spec').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r._has_enrollments);

const first = rows[0] || {};
const summary = first._summary || {};
const held = first._held || [];

const job_order = {
  client_id: cfg.client_id || null,
  ats_job_id: job.ats_job_id,
  title: job.title,
  description: job.description,
  required_skills: job.required_skills,
  nice_to_have: job.nice_to_have,
  city: job.city,
  state: job.state,
  pay_rate: job.pay_rate,
  shift: job.shift,
  employment_type: job.employment_type,
  recruiter_name: job.recruiter_name,
  recruiter_email: job.recruiter_email,
  status: 'open',
  raw: job.raw
};

const campaign = {
  client_id: cfg.client_id || null,
  name: job.campaign_name,
  // The ladder is COPIED onto the campaign, not referenced. Editing SEQUENCE in config
  // next week must not change the behaviour of a campaign already half way through.
  sequence: cfg.sequence,
  qualification: cfg.qualify,
  status: 'active',
  idempotency_key: job.idempotency_key
};

const candidates = rows.map((c) => ({
  client_id: cfg.client_id || null,
  ats_candidate_id: c.ats_candidate_id,
  first_name: c.first_name,
  last_name: c.last_name,
  email: c.email || null,
  phone_e164: c.phone_e164,
  title: c.title,
  skills: c.skills,
  city: c.city,
  state: c.state,
  timezone: c.timezone || cfg.default_timezone,
  ats_status: c.ats_status,
  last_ats_sync_at: new Date().toISOString()
}));

// The enrollment rows cannot be built yet — campaign_id and candidate_id are uuids Supabase
// has not minted. They are carried as natural keys and resolved by the next node from what
// the two upserts returned. Doing it this way rather than with 25 lookup calls is the
// difference between a launch that takes two seconds and one that takes ninety.
const enrollments = rows.map((c) => ({
  client_id: cfg.client_id || null,
  _ats_candidate_id: c.ats_candidate_id,
  _campaign_key: job.idempotency_key,
  _ats_job_id: job.ats_job_id,
  status: 'pending',
  match_score: c.match_score,
  match_reasons: c.match_reasons,
  step: 0,
  attempts_made: 0,
  next_attempt_at: c.next_attempt_at
}));

return [{
  json: {
    _write: cfg.supabase_enabled && !cfg.dry_run_db,
    job_order: job_order,
    campaign: campaign,
    candidates: candidates,
    enrollments: enrollments,
    held: held.map((h) => ({
      ats_candidate_id: h.ats_candidate_id,
      name: h.full_name,
      phone: h.phone_e164,
      match_score: h.match_score,
      hold_reason: h.hold_reason
    })),
    summary: summary
  }
}];

// Preview. Everything ran; nothing was written to Supabase and nothing was scheduled.
// Open this node to read the entire launch — who would be enrolled, in what order, with
// what score and for what reason, and everyone who was held back and why.
//
// This is the node to have on screen when a client asks "so what would it actually do".
const cfg = $('config').first().json;
const p = $input.first().json;

return [{
  json: {
    _outcome: 'preview — nothing enrolled',
    _why: cfg.demo_mode
      ? 'DEMO_MODE is on. It forces preview whatever TEST_RUN says, because a fabricated '
        + 'campaign must never be able to schedule a real text.'
      : (!cfg.supabase_enabled
        ? 'Supabase is not configured, so there is nowhere to write the campaign to.'
        : 'TEST_RUN is true with no TEST_PHONE set.'),
    job: p.campaign && p.campaign.name,
    would_enroll: (p.candidates || []).length,
    would_hold: (p.held || []).length,
    summary: p.summary,

    enrolling: (p.candidates || []).map((c, i) => {
      const e = (p.enrollments || [])[i] || {};
      return {
        rank: i + 1,
        name: (c.first_name + ' ' + c.last_name).trim(),
        ats_id: c.ats_candidate_id,
        phone: c.phone_e164,
        title: c.title,
        score: e.match_score,
        why: (e.match_reasons || []).join(' · '),
        first_touch_due: e.next_attempt_at
      };
    }),

    held_back: p.held || [],

    _next_step: 'Set DEMO_MODE = false and fill in SUPABASE_URL and SUPABASE_SERVICE_KEY '
      + 'to write this campaign. Nothing is sent even then — workflow 2 owns every send, '
      + 'and it has its own TEST_RUN gate.'
  }
}];

// Resolves the natural keys carried by `rows for supabase` into the uuids Supabase just
// minted, using what the two upserts returned rather than by looking anything up.
//
// Both upsert nodes send `Prefer: return=representation`, so the response IS the resolved
// row set. Twenty-five candidates cost one request and this node, instead of twenty-five
// select-by-ats_id calls — which is the difference between a launch that takes two seconds
// and one that takes a minute and a half against a rate-limited API.
const cfg = $('config').first().json;
const prepared = $('rows for supabase').first().json;

const asRows = (v) => {
  const j = v && v.json !== undefined ? v.json : v;
  if (Array.isArray(j)) return j;
  if (j && Array.isArray(j.data)) return j.data;
  return j ? [j] : [];
};

const campaignRows = $('[cred] Supabase - upsert the campaign').all().flatMap(asRows);
const candidateRows = $input.all().flatMap(asRows);
const jobRows = $('[cred] Supabase - upsert the job order').all().flatMap(asRows);

const campaign = campaignRows.find((r) => r && r.id) || {};
const jobRow = jobRows.find((r) => r && r.id) || {};

const byAtsId = new Map();
for (const r of candidateRows) {
  if (r && r.id && r.ats_candidate_id) byAtsId.set(String(r.ats_candidate_id), r.id);
}

const unresolved = [];
const enrollments = [];

for (const e of prepared.enrollments || []) {
  const candidate_id = byAtsId.get(String(e._ats_candidate_id));
  if (!candidate_id || !campaign.id || !jobRow.id) {
    unresolved.push({
      ats_candidate_id: e._ats_candidate_id,
      missing: !candidate_id ? 'candidate row' : (!campaign.id ? 'campaign row' : 'job order row')
    });
    continue;
  }
  enrollments.push({
    client_id: cfg.client_id || null,
    campaign_id: campaign.id,
    candidate_id: candidate_id,
    job_order_id: jobRow.id,
    status: e.status,
    match_score: e.match_score,
    match_reasons: e.match_reasons,
    step: e.step,
    attempts_made: e.attempts_made,
    next_attempt_at: e.next_attempt_at
  });
}

// An enrollment that cannot be linked is reported, not silently skipped. It is nearly
// always the upsert returning fewer rows than were sent because one of them violated a
// constraint, and that is worth seeing in the execution list.
return [{
  json: {
    campaign_id: campaign.id || null,
    job_order_id: jobRow.id || null,
    enrollments: enrollments,
    linked: enrollments.length,
    unresolved: unresolved,
    _warning: unresolved.length
      ? unresolved.length + ' enrollment(s) could not be linked to a Supabase row. '
        + 'Check the upsert responses above for a constraint violation.'
      : ''
  }
}];

// The Slack message. Written so a recruiting manager who knows nothing about n8n can read
// it in five seconds and tell whether the morning went well.
const cfg = $('config').first().json;
const p = $('rows for supabase').first().json;
const s = p.summary || {};
const held = p.held || [];

const byReason = Object.entries(s.held_by_reason || {})
  .sort((a, b) => b[1] - a[1])
  .map(([reason, n]) => '• ' + n + ' — ' + reason);

const enrolled = (p.candidates || []).length;
const top = (p.enrollments || []).slice(0, 3).map((e, i) => {
  const c = (p.candidates || [])[i] || {};
  return '  ' + (i + 1) + '. ' + ((c.first_name + ' ' + c.last_name).trim() || c.ats_candidate_id)
    + ' (' + e.match_score + ') — ' + (e.match_reasons || []).slice(0, 2).join(', ');
});

const modeLabel = cfg.mode === 'live' ? '' : '  [' + cfg.mode.toUpperCase() + ']';

const lines = [
  '*Candidate engine — campaign launched*' + modeLabel,
  (p.campaign && p.campaign.name) || 'campaign',
  '',
  'Pool scored: ' + (s.pool || 0) + '   Enrolled: ' + enrolled + '   Held: ' + held.length,
  ''
];
if (top.length) lines.push('Top matches:', ...top, '');
if (byReason.length) lines.push('Held back:', ...byReason, '');
lines.push('First touches are scheduled. The outreach runner sends them on its next pass.');

// Anything a human needs to act on, rather than just read.
const attention = [];
if (!cfg.supabase_enabled) attention.push('Supabase not configured — nothing was persisted.');
if (!cfg.twilio_enabled) attention.push('Twilio not configured — the scheduled touches cannot send.');
if (!cfg.ats_enabled) attention.push('ATS not connected — this ran against the sample pool.');
const noPhone = held.filter((h) => String(h.hold_reason).startsWith('no usable mobile')).length;
if (noPhone > 2) {
  attention.push(noPhone + ' candidates had no usable mobile — check the phone field mapping.');
}
if (attention.length) lines.push('', '*Needs attention*', ...attention.map((a) => '• ' + a));

return [{
  json: {
    _outcome: 'campaign launched',
    enrolled: enrolled,
    held: held.length,
    pool: s.pool || 0,
    needs_attention: attention,
    slack_text: lines.join('\n'),
    // Slack's incoming-webhook shape. One field, so swapping Slack for Teams is one node.
    slack_payload: { text: lines.join('\n') }
  }
}];
